// Tiny raster fixtures generated by a browser canvas, without embedded metadata.
import { deflateSync } from "node:zlib";

export function pngPoster(width = 128, height = 128): Buffer {
  function chunk(kind: string, content: Buffer) {
    const data = Buffer.concat([Buffer.from(kind), content]);
    let crc = 0xffffffff;
    for (const byte of data) {
      crc ^= byte;
      for (let bit = 0; bit < 8; bit++) crc = (crc >>> 1) ^ (crc & 1 ? 0xedb88320 : 0);
    }
    const length = Buffer.alloc(4);
    length.writeUInt32BE(content.length);
    const checksum = Buffer.alloc(4);
    checksum.writeUInt32BE((crc ^ 0xffffffff) >>> 0);
    return Buffer.concat([length, data, checksum]);
  }
  const header = Buffer.alloc(13);
  header.writeUInt32BE(width);
  header.writeUInt32BE(height, 4);
  header[8] = 8;
  header[9] = 2;
  const raw = Buffer.alloc((width * 3 + 1) * height);
  let seed = 42;
  for (let offset = 0; offset < raw.length; offset++) {
    seed = (Math.imul(seed, 1664525) + 1013904223) >>> 0;
    raw[offset] = offset % (width * 3 + 1) ? seed >>> 24 : 0;
  }
  return Buffer.concat([
    Buffer.from("89504e470d0a1a0a", "hex"),
    chunk("IHDR", header),
    chunk("IDAT", deflateSync(raw)),
    chunk("IEND", Buffer.alloc(0)),
  ]);
}
export const jpegPoster = Buffer.from(
  "",
  "base64",
);
export const webpPoster = Buffer.from("UklGRiQAAABXRUJQVlA4IBgAAAAwAQCdASoCAAMAAUAmJaQAA3AA/v02aAA=", "base64");
